    {
        if (isCnStakingV2(staking)) {
            // Only recognize those configured with the official StakingTracker.
            address tracker = ICnStakingV2(staking).stakingTracker();
            if (tracker == 0x8Fe0f06DF2C95B8D5D9D4232405614E505Ab04C0) {
